{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "c2b861fjOzf-j874_vFn6w",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "A colossal stone gate, cracked and overgrown with thorny vines, stands before the group. Old royal banners, faded and torn, flutter from the battlements.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The lamp's flame-eye flickers as it casts a flickering light on a distant, spiraling tower wrapped in shadow. The ground is littered with broken masonry.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Tin Fox scouts the empty marketplace.",
      "visual_description": "The tin fox darts between abandoned stalls, its metal paws clicking on cobblestones. Faded canopies flap in the wind.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver peers through a shattered mirror.",
      "visual_description": "He leans into a large broken mirror propped against a wall, his diving helmet reflecting a distorted image of a locked courtyard beyond.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Mara the Cartographer deciphers a worn map.",
      "visual_description": "She unrolls a parchment on a stone table, tracing a faded ink line with her finger. The compass on her coat gleams dully.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The party finds a sleeping tax collector in a guardhouse.",
      "visual_description": "Inside a dusty guardhouse, the sleeping tax collector snores with a ledger under his head. Stamped papers are stuck to his sleeves.",
      "characters": ["sleeping_tax_collector", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp illuminates a magic door.",
      "visual_description": "The lamp's glow reveals a door covered in shifting runes, set into a windowless wall. The air hums faintly.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The Tin Fox triggers a hidden alarm.",
      "visual_description": "The fox's tail brushes a tripwire, and a brass bell clangs loudly. Armored patrols in the distance turn toward the sound.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "The Glass Diver swims through a window to unlock the magic door.",
      "visual_description": "He presses his helmet against a window pane, then steps through as if into water, emerging inside the room beyond. He turns a rusty lock.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Mara leads the group through the now-open door.",
      "visual_description": "The door swings open into a dark corridor. Mara holds the compass, her coat stained with ink, her expression focused.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "The Oracle Lamp warns of a trap ahead.",
      "visual_description": "The flame-eye narrows as it casts a beam onto a section of floor that seems slightly uneven. Shadows crawl along the walls.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "The Tin Fox disables the pressure plate.",
      "visual_description": "The metal fox carefully inserts its key-wind tail into a mechanism beneath a loose stone, clicking it into a safe position.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The sleeping tax collector wakes briefly.",
      "visual_description": "He stirs, mumbles something about 'proper forms', then falls back asleep, papers rustling around him.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The Glass Diver sees the rescue target through a mirror.",
      "visual_description": "He touches a silvered glass, and in its reflection he sees a figure huddled in a distant cell. He signals the others.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Mara finds the final key on the tax collector's ring.",
      "visual_description": "She carefully lifts a brass key from the sleeping official's belt loop, trying not to wake him. The lamp glows approvingly.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The party unlocks the cell and frees the captive.",
      "visual_description": "The key turns in a heavy lock, the cell door creaks open. The rescued figure steps out, blinking in the lamp's light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols block the path to the bridge.",
      "visual_description": "At the end of a long street, a line of armored figures stand before a stone bridge. Their weapons gleam in the dim light.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "The Glass Diver creates a mirror path across the bridge.",
      "visual_description": "He shatters a nearby window and steps through the shards, forming a shimmering path of reflections that the party runs across. The bridge is crossed.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

